import{_ as a,o as r,c as e,a2 as p}from"./chunks/framework.F7eQ-ohH.js";const d="/bzygq/assets/quesion_imgs_ce566f33ed64482ba18ee9bd3d5092cb.B5gkhGPI.png",n="/bzygq/assets/quesion_imgs_0334f58175e04abbb237b02e4da56011.BHxMD_Hv.png",o="/bzygq/assets/quesion_imgs_bc054990305041ca9086d1609ec00645.DvULJBNY.png",s="/bzygq/assets/quesion_imgs_e63def7403fa491099d24fd416511bde.J149Q-HV.png",i="/bzygq/assets/quesion_imgs_931be4fb5d934c48a2107739fa2cec27.BlPjORuU.png",u=JSON.parse('{"title":"增长率相关概念","description":"","frontmatter":{},"headers":[],"relativePath":"行测/资料分析/3.增长率.md","filePath":"行测/资料分析/3.增长率.md","lastUpdated":1788883925000}'),h={name:"行测/资料分析/3.增长率.md"};function l($,t,c,_,b,f){return r(),e("div",null,[...t[0]||(t[0]=[p('<h1 id="增长率相关概念" tabindex="-1">增长率相关概念 <a class="header-anchor" href="#增长率相关概念" aria-label="Permalink to &quot;增长率相关概念&quot;">​</a></h1><h2 id="思维导图" tabindex="-1">思维导图 <a class="header-anchor" href="#思维导图" aria-label="Permalink to &quot;思维导图&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><h2 id="增长率" tabindex="-1">增长率 <a class="header-anchor" href="#增长率" aria-label="Permalink to &quot;增长率&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>增长率是表述基期量与现期量变化的相对量，增长率又称增速、增幅或者增长幅度增值率等，增长率为负时表示下降，增长率的计算公式如下：</p><p>$$ \\text{增长率} = \\frac{\\text{增长量}}{\\text{基期}} = \\frac{\\text{增长量}}{\\text{现期} - \\text{增长量}} = \\frac{\\text{现期} - \\text{基期}}{\\text{基期}} $$</p><p>例如，如果某公司2022年的收入为100万元，2023年的收入为120万元，那么2023年的收入增长率就是20%。</p><h1 id="年均增长率" tabindex="-1">年均增长率 <a class="header-anchor" href="#年均增长率" aria-label="Permalink to &quot;年均增长率&quot;">​</a></h1><h2 id="年均增长率-1" tabindex="-1">年均增长率 <a class="header-anchor" href="#年均增长率-1" aria-label="Permalink to &quot;年均增长率&quot;">​</a></h2><p>如果假设第一年为A，第n+1年为B，这n年的<strong>年均增长率为r</strong>，那么： $$</p><p>B=A(1+r)^n</p><p>$$</p><p>$$ r=\\sqrt[n]{\\frac{B}{A} }-1 $$</p><p>如果n=1，此时的年均增长率等于年增长率，则有：</p><p>$$ r=\\frac{B}{A}-1 $$</p><p>如n年间的增长率分别为 $$r_1$$，$$r_2$$，...，$$r_n$$ ,年均增长率为 ，则 $$(1+r)^n=(1+r_1)(1+r_2)...(1+r_n)$$，从而:</p><p>$$ r=\\sqrt[n]{(1+r_1)(1+r_2)...(1+r_n)} -1 $$</p><h2 id="年平均增长率" tabindex="-1">年平均增长率 <a class="header-anchor" href="#年平均增长率" aria-label="Permalink to &quot;年平均增长率&quot;">​</a></h2><p>年均增长率顾名思义就是增长率平摊到每一年的增长率,用公式表达的话就是将所有年的增长率相加，再除以年份：</p><p>$$ \\frac{r_1+r_2+...+r_n}{n} $$</p><p>需要注意的是，一般年平均增长率是大于年均增长率的，即：</p><p>$$ \\frac{r_1+r_2+...+r_n}{n} &gt; \\frac{r_1+r_2+...+r_n}{n} $$</p><h2 id="总增长率" tabindex="-1">总增长率 <a class="header-anchor" href="#总增长率" aria-label="Permalink to &quot;总增长率&quot;">​</a></h2><p>假设第一年为A，第n年为B，那么总增长率就是从第一年到第n年的增长率，公式如下：</p><h2 id="实例分析" tabindex="-1">实例分析 <a class="header-anchor" href="#实例分析" aria-label="Permalink to &quot;实例分析&quot;">​</a></h2><p>例题：如果 2001 年广东省工业污染治理国家预算内资金为 3.10 亿元，则 2001 至 2003 年，该项资金年均增长率约为：</p><p>A . 75 % B . 60 % C . 50 % D . 36 %</p><p>解析：关键词“广东”，“国家预算内资金”，解题点定位在表格第三列倒数第二行，由年均增长率公式；</p><p>$$ r=\\sqrt[n]{\\frac{B}{A} }-1 ；\\frac{B}{A}=\\frac{6.97}{3.1}=2.2;r=\\sqrt[2]{2.2}-1=0.5 $$</p><h1 id="增长率、降幅、变化幅度的区别" tabindex="-1">增长率、降幅、变化幅度的区别？ <a class="header-anchor" href="#增长率、降幅、变化幅度的区别" aria-label="Permalink to &quot;增长率、降幅、变化幅度的区别？&quot;">​</a></h1><h2 id="增长率、降幅、变化幅度概念" tabindex="-1">增长率、降幅、变化幅度概念 <a class="header-anchor" href="#增长率、降幅、变化幅度概念" aria-label="Permalink to &quot;增长率、降幅、变化幅度概念&quot;">​</a></h2><ol><li><strong>幅度与增长率</strong>：幅度本质是指标在一定时期内的变化程度（即增长率），可正可负 —— 正值代表增长，负值代表减少，常用于经济数据、股票价格、人口数量等场景。例如，公司年利润增加 10% 则利润增幅（增长率）为 10%，城市人口减少 2% 则人口增幅（增长率）为 - 2%。增长率侧重衡量变化速度，比较时需关注正负号以明确变化方向，如项目 A 年化增长率 5% 优于项目 B 的 - 10%。</li><li><strong>降幅</strong>：特指指标减少的程度，仅适用于下降场景。比较降幅时聚焦绝对值（不考虑正负），核心衡量 “减少多少”。例如，商品价格从 100 元降至 95 元（降幅 5%），另一商品降至 85 元（降幅 15%），后者降幅更大。</li><li><strong>变化幅度</strong>：描述指标增长或减少的绝对比率，是非负值，仅体现变化大小而非方向。计算时取增长率的绝对值，若 A 项目上涨 10%、B 项目下降 10%，二者变化幅度均为 10%。</li></ol><h2 id="实例分析-1" tabindex="-1">实例分析 <a class="header-anchor" href="#实例分析-1" aria-label="Permalink to &quot;实例分析&quot;">​</a></h2><p>1.2023 年收入 10 万元，同比增长 10%，增速比去年提高 5 个百分点，求 2022 年增长率？</p><p>解析：“提高” 表示今年增速较去年上升，用减法计算，2022 年增长率 = 10%-5%=5%。</p><p>2.2023 年收入 10 万元，同比增长 10%，增速比去年回落 5 个百分点，求 2022 年增长率？</p><p>解析：“回落” 表示今年增速较去年下降，用加法计算，2022 年增长率 = 10%+5%=15%。</p><p>3.2023 年收入 10 万元，同比下降 10%，降幅比去年扩大 5 个百分点，求 2022 年降幅及增长率？</p><p>解析：降幅计算不考虑正负号，“扩大” 意味着今年降幅比去年更大，故 2022 年降幅 = 10%-5%=5%；增长率需体现下降方向，即 - 5%。</p><p>4.2023 年收入 10 万元，同比下降 10%，降幅比去年收窄 5 个百分点，求 2022 年降幅及增长率？</p><p>解析：“收窄” 表示今年降幅比去年更小，降幅计算用加法，2022 年降幅 = 10%+5%=15%；增长率对应为 - 15%。</p><h1 id="增长率比较" tabindex="-1">增长率比较 <a class="header-anchor" href="#增长率比较" aria-label="Permalink to &quot;增长率比较&quot;">​</a></h1><h2 id="增长率比较定义" tabindex="-1">增长率比较定义 <a class="header-anchor" href="#增长率比较定义" aria-label="Permalink to &quot;增长率比较定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>增速最快/最慢：增速快慢通常通过增长率来衡量。增长率越大，增速越快；增长率越小，增速越慢。增长率可以是正数也可以是负数，正数表示增长，负数表示减少。</th></tr></thead></table><table tabindex="0"><thead><tr><th>增长幅度最大/最小：增长幅度通常指的是增长的绝对值，无论是增长还是减少。增长幅度越大，变化越显著；增长幅度越小，变化越微弱。增长幅度的计算方法是取增长率的绝对值。</th></tr></thead></table><p>已知现期值和基期值，需要比较增长率，设增长率用r表示，则公式式如下：</p><p>$$ r=\\frac{现期-基期}{基期}=\\frac{现期}{基期}-1<br> $$</p><p>在比较多个增长率时，可以简化计算过程。例如，如果有两个增长率 和 ，分别由以下公式计算：</p><p>$$ r_1=\\frac{A}{B}-1<br> $$</p><p>$$ r_2=\\frac{C}{D}-1<br> $$</p><p>由于每个公式中都有一个“-1”，可以直接比较和 $$\\frac{A}{B}$$、$$\\frac{C}{D}$$ 的大小，从而确定增长率的大小。</p><h2 id="快速比较方法" tabindex="-1">快速比较方法 <a class="header-anchor" href="#快速比较方法" aria-label="Permalink to &quot;快速比较方法&quot;">​</a></h2><p>想要快速比较2个场景得增长率，我们需要看现期和基期的倍数关系是否明显，通过这个来可以快速的进行判断</p><ul><li><p>当$$\\frac{现期}{基期}=1+不明显$$ ：如果现期值和基期值相差不大，即现期值与基期值的比值接近1，此时直接用<strong>增长率</strong> 进行比较更为准确。</p></li><li><p>当$$\\frac{现期}{基期}=2+明显$$ ：如果现期值明显大于基期值，即现期值与基期值的比值明显大于1，此时可以直接用现$$\\frac{基期}{现期}$$的比值进行比较，这样可以简化计算过程。</p></li></ul><h2 id="实例分析-2" tabindex="-1">实例分析 <a class="header-anchor" href="#实例分析-2" aria-label="Permalink to &quot;实例分析&quot;">​</a></h2><p>例：下图2012年-2015年，哪一年的同比增速最快？</p><p><img src="'+o+'" alt=""></p><p>解析：图中看倍数关系明不明显，2011年跟 2012年倍数关系明显，直接用426/133=3+，866/426=2+，1600/866=1+，1800/1600=1+，明显 2012 年增速最大。</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><p><strong>例1：2012年~2021年全国羊肉产量年度变化情况如下图所示，则2021年，全国羊肉产量同比增长率约为（）</strong></p><p><img src="'+s+'" alt=""></p><p>2012年~2021年全国羊肉产量年度变化情况</p><p>A. 2.4%</p><p>B. 3.4%</p><p>C. 4.4%</p><p>D. 5.4%</p><p>解析：根据题干“2021 年，全国羊肉产量同比增长率约为”，可判定本题为一般增长率问题。定位图1可知 2020 年、2021 年全国羊肉产量分别为 492.3 万吨、514.1 万. 根据公式:增长率= $$\\frac{现期-基期}{基期} $$，则 2021 年全国羊肉产量同比增长率为 $$\\frac{514.1-492.3}{492.} $$ ≈4.4%。故正确答案为C</p><p><strong>例2： (2019 广东)，如下表为2016-2018年全国电力工业统计数据(部分)</strong></p><table tabindex="0"><thead><tr><th>指标名称</th><th>2018 年</th><th>2017 年</th><th>2016 年</th></tr></thead><tbody><tr><td>可再生能源发电量(亿千瓦时)</td><td>18700</td><td>17000</td><td>15500</td></tr><tr><td>其中: 水电发电量(亿千瓦时)</td><td>12000</td><td>11945</td><td>11745</td></tr><tr><td>风电发电量(亿千瓦时)</td><td>3660</td><td>3057</td><td>2420</td></tr><tr><td>光伏发电发电量(亿千瓦时)</td><td>1775</td><td>1182</td><td>662</td></tr><tr><td>生物质发电发电量(亿千瓦时)</td><td>906</td><td>794</td><td>647</td></tr><tr><td>全口径发电设备容量(万千瓦)</td><td>177703</td><td>189967</td><td>165151</td></tr></tbody></table><p>2017年，下列可再生能源发电量同比增幅最大的是:</p><p>A.水电</p><p>B.风电</p><p>C.光伏发电</p><p>D.生物质发电</p><p>解析：C。解析:增幅最大，即增长率最大，判定题型为增长率比较问题。2017年同比是和 2016 年做比较，对应材料找数据，不需要看 2018年的数据，表格中的数据都是 1倍多的关系，用“(现期-基期)/基期“做比较。A顶:(11945-11745)/11745=200/11745；B项:(3057-2420)/2420=637/2420；C项:(1182-662)/662=520/662；D项:(794-647)/647=147/647，可以看出C项明显最大，故选C。</p><p><strong>例3：7月 28 日~8月5日间，A影片票房环比增速最快的单日，当日A影片占全国总票房/5:的比例在该影片上映 10 天内排名（）</strong></p><p><img src="'+i+'" alt=""></p><p>A.第7</p><p>B.第6</p><p>C.第5</p><p>D.第4</p><p>解析：先找到当日的比例再进行排名，注意问的是环比增速最快的，环比按最小的统计周期(天)相比，即和上一天比，增速比较问题，看“现期/基期“倍数关系明显不明显。r7月 28日=2.15/1.03=2+，倍数关系明显，直接用“现期/基期“做比较,除了 7月 28 日，其余日期的环比增长率都没有2倍以上的关系，即7月 28 日的环比增长率最大，占全国总票房的比例是 73.5%,看其余日期的比例,一共有3天(58.3%、54.7%.66.3%)的比例比 73.5%低，一共有 10 天，即 7月 28 日排名第 7。故选 A。</p>',83)])])}const m=a(h,[["render",l]]);export{u as __pageData,m as default};
